import sys,re
sys.path.insert(0,"engine")
from odata_client import ODataClient
c=ODataClient()
vid={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_ВидОплаты", select=["Ref_Key","Description"])}
cur={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_Валюты", select=["Ref_Key","Description"])}
n=0
for r in c.list("Document_Счет"):
    if str(r.get("СтатусСчета") or "")!="Оплачен": continue
    n+=1
    if n>3: break
    print("=== рахунок %s від %s | вид оплати: %s | валюта: %s | дата оплати %s"%(
        r.get("Number"), str(r.get("Date"))[:10], vid.get(r.get("видОплаты_Key")),
        cur.get(r.get("Валюта_Key")), str(r.get("ДатаОплаты"))[:10]))
    for k,v in r.items():
        if re.search(r"Сумм|Сум",k) and not k.endswith("_Key"):
            try:
                f=float(v)
            except (TypeError,ValueError):
                continue
            if abs(f)>0.004: print("      %-26s %.2f"%(k,f))
EOF
